async function loadModels() {
  if (globalThis.TORRE_MODELS) return globalThis.TORRE_MODELS;
  const entries = await Promise.all(
    MODEL_IDS.map(async (id) => {
      const res = await fetch(new URL("./" + id + ".json", globalThis.location.href));
      const json = await res.json();
      return [id, json];
    })
  );
  const out = {};
  for (const [id, json] of entries) out[id] = json;
  return out;
}

